                const x = Math.max(0, Math.min(100, ((pointer.clientX - rect.left) / rect.width) * 100));
                const y = Math.max(0, Math.min(100, ((pointer.clientY - rect.top) / rect.height) * 100));
                surface.style.setProperty('--glass-light-x', `${x.toFixed(1)}%`);
