                const remain = Math.max(0, ATTACHMENT_MAX_FILES - existingAttachments);
                if (remain <= 0) {
                    showToast(`添付は最大${ATTACHMENT_MAX_FILES}件です`, "error", true);
                    return;
                }
                allowedIncoming = incoming.slice(0, remain);
