            rich_paste_prompt_default: { label: 'リッチ貼り付けプロンプト', modal: 'rich-paste', control: 'rich-paste-prompt' },
            rich_paste_prompt_use_custom_default: { label: 'リッチ貼り付けの既定値', modal: 'rich-paste', control: 'rich-paste-use-default' }
